section={1:'Ch. 1: Thinking Like a Linguist',2:'Chs. 1–10: areas and methods; field definitions in supplied lecture',3:'Chs. 2–4: speech sounds, transcription and contrast',4:'Chs. 6–8: word forms, word classes and phrases',5:'Ch. 1: mental grammar; supplied Lecture 5',6:'Chs. 8–9: sentence structure and meaning',7:'Chs. 9–10; 2nd ed. Ch. 7: semantics',8:'2nd ed. Ch. 8: pragmatics'}
rng=random.Random(182026)
for lec in range(1,9):
 group=[c for c in concepts if c['lecture']==lec]
 for i,c in enumerate(group,1):
  c['id']=f'L{lec}-C{i:02d}';c['origin']='Handout topic, clarified' if i in core[lec] else 'Supplementary revision'
  c['sourceIds']=['essentials2'] if lec==8 else ['anderson','essentials2']
  if lec==3:c['sourceIds'].append('ipa')
  c['referenceSection']=section[lec]
  others=[x for x in group if x is not c]
  # Nearby concepts yield plausible alternatives rather than unrelated whole-course options.
  idx=group.index(c); near=[group[(idx+j)%len(group)] for j in [1,2,3,4,-1,-2,-3,-4]]
  distract=rng.sample(near,3)
  variants=[
   (['Which term best matches this definition?','Identify the concept described below.','Which concept is defined by the following description?'][i%3]+'\n'+c['definition'],[c['term']]+[d['term'] for d in distract],0,'Definition','Foundational'),
   (['Which concept is most directly illustrated by this example?','Which analysis best identifies the main concept in this case?','Read the case and choose the most appropriate concept.'][i%3]+'\n'+c['example'],[c['term']]+[d['term'] for d in distract],0,'Application','Applied'),
   (['Which description most accurately defines','Choose the best definition of','Which account correctly characterizes'][i%3]+' '+c['term']+'?',[c['definition']]+[d['definition'] for d in distract],0,'Concept comparison','Foundational'),
   ('Which statement about '+c['term']+' is INACCURATE?',[c['false'],c['definition'],c['note'],'An illustration is: '+c['example']],0,'Misconception check','Analytical')]
  for v,(q,opts,ans,kind,level) in enumerate(variants,1):
   if v==3: continue  # Omit inverse-definition items that duplicate the first retrieval task.
   # Independently shuffle all options; there is no fixed repeating answer-letter cycle.
   indices=list(range(4));rng.shuffle(indices)
   answer=indices.index(ans)
   exp=c['definition']+'\nExample: '+c['example']+'\nImportant distinction: '+c['note']
   if v==4:exp='The inaccurate claim is: “'+c['false']+'”\n'+exp
   bank.append(dict(id=f'L{lec}-{(i-1)*4+v:03d}',lecture=lec,topic=c['term'],conceptId=c['id'],question=q,options=[opts[j] for j in indices],answer=answer,type=kind,level=level,explanation=exp,origin=c['origin'],sourceIds=c['sourceIds'],referenceSection=section[lec]))
